// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface DoctorShiba {
    function owner() external view returns (address);
    function pause() external;
    function paused() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner directly
        // Label the contract for debugging
        vm.label(TARGET, "DoctorShiba");

        // Get the current owner
        address owner = DoctorShiba(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get the current owner
        address owner = DoctorShiba(TARGET).owner();

        // Step 2: Impersonate the owner and pause the contract
        vm.prank(owner);
        DoctorShiba(TARGET).pause();

        // Step 3: Verify the contract is paused
        bool isPaused = DoctorShiba(TARGET).paused();
        require(isPaused, "Contract should be paused");

        // The oracle will check that paused == true
        assertEq(isPaused, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
